class Publicacion {
  var esPrivada
  const property creador = new Usuario()
  const property fechaPublicacion = new Date()

  method volverPrivada() {
    esPrivada = true
  }

  method volverPublica() {
    esPrivada = false
  }

  method puedeVerla(unaPersona, _unDia) {
    return not esPrivada or creador.tieneContacto(unaPersona) or unaPersona == creador
  }
}


class Historia inherits Publicacion {
  override method puedeVerla(unaPersona, unDia) {
    return super(unaPersona, unDia) and unDia <= fechaPublicacion.plusDays(1) or unaPersona == creador
  }
}


const historiaPublica = new Historia(esPrivada = false)


const publicacionPrivada = new Publicacion(esPrivada = true)

